// src/github-copilot/responses/openai-error.ts
import { z } from "zod/v4";
import { createJsonErrorResponseHandler } from "@ai-sdk/provider-utils";
var openaiErrorDataSchema2 = z.object({
  error: z.object({
    message: z.string(),
    type: z.string().nullish(),
    param: z.any().nullish(),
    code: z.union([z.string(), z.number()]).nullish()
  })
});
var openaiFailedResponseHandler2 = createJsonErrorResponseHandler({
  errorSchema: openaiErrorDataSchema2,
  errorToMessage: (data) => data.error.message
});

export { openaiErrorDataSchema2, openaiFailedResponseHandler2 };
